function ccType(s){return /ex.dividend|dividend rights/i.test(s)?'ex_dividend':/dividend.*pay|payment.*dividend/i.test(s)?'dividend_payment':/annual general|shareholder.*meeting|\bagm\b/i.test(s)?'shareholder_meeting':/earnings|results|revenue|sales/i.test(s)?'earnings':/annual report/i.test(s)?'annual_report':/investor|roadshow|conference|capital markets/i.test(s)?'investor_event':null;}
