function pfCommand(c){const args=c.args||[],p=pfCurrent(c),usage='/position TICKER EXCHANGE WEIGHT_PERCENT | optional sector label\n/cash WEIGHT_PERCENT\n/portfolio';if(c.original_action==='portfolio'){if(!args.length)return {text:pfDashboard(c),links:[]};if(args.length===1&&args[0]==='new'){pfSave(c,{mode:'actual',positions:{},cash_bps:null},'Started empty actual portfolio');return {text:'Started an empty real portfolio. Previous snapshot retained in recent history.\n'+usage,links:[]};}return {text:'Use /portfolio to view, or /portfolio new to start an empty real portfolio.',links:[]};}let positions={...(p?.positions||{})},cash=p?.cash_bps??null,event='';const parse=s=>{if(!/^\d+(?:\.\d{1,2})?%?$/.test(String(s||'')))return null;const n=Number(String(s).replace('%',''));return n>=0&&n<=100?Math.round(n*100):null;};if(c.original_action==='cash'){if(args.length!==1||parse(args[0])===null)return {text:'Use /cash PERCENT between 0 and 100, with up to two decimal places.',links:[]};cash=parse(args[0]);if(cash===p?.cash_bps)return {text:'Cash weight is already saved. No change.',links:[]};event='Cash allocation updated';}else{const parts=args.join(' ').split('|').map(s=>s.trim()),[ticker,exchange,weight,...extra]=(parts[0]||'').split(/\s+/);const s=c.universe.find(s=>s.ticker.toUpperCase()===String(ticker).toUpperCase()&&s.exchange.toUpperCase()===String(exchange).toUpperCase()),bps=parse(weight);if(!s||extra.length||parts.length>2||bps===null||(parts.length===2&&(!parts[1]||parts[1].length>60)))return {text:'Choose a listing from /universe and a nonnegative weight up to 100 with two decimal places. Sector label is optional (1–60 characters).\n'+usage,links:[]};if(bps===0){if(!positions[s.stock_id])return {text:'That position is already absent. No change.',links:[]};delete positions[s.stock_id];event='Removed '+s.stock_id;}else{const value={weight_bps:bps,sector:parts[1]||positions[s.stock_id]?.sector||''};if(JSON.stringify(value)===JSON.stringify(positions[s.stock_id]))return {text:'This position is already saved. No change.',links:[]};positions[s.stock_id]=value;event='Updated '+s.stock_id;}}const total=Object.values(positions).reduce((s,v)=>s+v.weight_bps,0)+(cash||0);if(total>10000)return {text:'Not saved: stock weights plus specified cash would total '+pfPercent(total)+'. Reduce another allocation first; the total must not exceed 100%.',links:[]};const next=pfSave(c,{mode:p?.mode||'actual',positions,cash_bps:cash},event);return {text:(next.mode==='demo'?'DEMO PORTFOLIO':'TEAM PORTFOLIO')+' updated.\n'+event+'\nSpecified '+pfPercent(total)+' · unspecified '+pfPercent(10000-total)+'\n/portfolio',links:[]};}

// Saved report deltas, research reference outcomes and explicit catalyst provenance.
function rbHash(v){let h=2166136261;for(const ch of JSON.stringify(v))h=Math.imul(h^ch.charCodeAt(0),16777619);return (h>>>0).toString(16).toUpperCase();}
function rbDelivered(c){return Object.values(c.state.Briefings||{}).filter(b=>!b.content_review_required&&b.chunks?.length&&b.chunks.every(p=>p.status==='sent')).sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at));}
function rbSnapshot(c){const events={};for(const e of Object.values(c.state.Events||{}).filter(e=>e.status==='analysed'&&e.analysis&&Date.parse(e.published_on)<=Date.now()&&Date.now()-Date.parse(e.published_on)<=Number(c.cfg.max_news_age_days||7)*86400000).sort((a,b)=>Date.parse(b.published_on)-Date.parse(a.published_on)).slice(0,20)){events[e.event_id]={ref:twCaseRef(e),fingerprint:researchFingerprint(e),summary:twSummary(e,170)};}const earnings={},theses={},catalysts={},calendar={};for(const [key,e] of Object.entries(c.state.Earnings||{}))if(e.status==='evidence_checked')earnings[key]=rbHash(e.facts);for(const [key,t] of Object.entries(c.state.Meta||{})){if(t.kind==='calendar_observation')calendar[key]=rbHash([...(t.issuer_events||[]),...(t.provider_events||[])].map(e=>[e.type,e.date,e.date_end,e.verification]));if(t.kind==='team_thesis')theses[key]={stock_id:t.stock_id,revision:t.revision,status:t.status};if(t.kind==='team_catalyst')catalysts[key]={id:t.id,status:t.status,revision:t.revision};}while(JSON.stringify(events).length>18000&&Object.keys(events).length>1)delete events[Object.keys(events).at(-1)];return {events,earnings,theses,catalysts,calendar,portfolio:pfCurrent(c)?{revision:pfCurrent(c).revision,mode:pfCurrent(c).mode}:null};}
function rbDelta(c){const current=rbSnapshot(c),previous=rbDelivered(c)[0],old=previous?.research_snapshot;const lines=['WHAT CHANGED'];if(!old){lines.push('First comparison baseline: this report records the current research state. Changes will be measured against a previously delivered report.');return {text:lines.join('\n'),snapshot:current};}lines.push('Since delivered brief '+previous.run_id+' · '+previous.created_at);let changes=0;for(const [id,e] of Object.entries(current.events)){const p=old.events?.[id];if(!p||p.fingerprint!==e.fingerprint){changes++;if(changes<=3)lines.push((p?'UPDATED':'NEW')+' · '+e.summary,'/case '+e.ref);}}if(changes>3)lines.push('Plus '+(changes-3)+' further new/updated tracked cases. /queue');let earnings=0;for(const [id,f] of Object.entries(current.earnings))if(old.earnings?.[id]!==f)earnings++;if(earnings)lines.push(earnings+' issuer result record(s) added or changed; inspect /earnings.');let theses=0;for(const [id,t] of Object.entries(current.theses))if(JSON.stringify(old.theses?.[id])!==JSON.stringify(t))theses++;if(theses)lines.push(theses+' team thesis journal(s) changed. /theses');let catalysts=0;for(const [id,t] of Object.entries(current.catalysts))if(JSON.stringify(old.catalysts?.[id])!==JSON.stringify(t))catalysts++;if(catalysts)lines.push(catalysts+' team catalyst plan(s) changed. /catalysts');let calendarChanges=0;for(const [id,h] of Object.entries(current.calendar||{}))if(old.calendar?.[id]!==h)calendarChanges++;if(calendarChanges)lines.push(calendarChanges+' company calendar(s) added or changed. /catalysts');const portfolioChanged=JSON.stringify(current.portfolio||null)!==JSON.stringify(old.portfolio||null);if(portfolioChanged)lines.push('Portfolio allocation snapshot changed. /portfolio');if(!changes&&!earnings&&!theses&&!catalysts&&!portfolioChanged&&!calendarChanges)lines.push('No changes in the tracked research snapshot.');lines.push('Compares up to 20 recent validated cases plus saved results and team records; new headlines awaiting analysis are excluded.');return {text:lines.join('\n'),snapshot:current};}
function rbPct(v){return (v>=0?'+':'')+(v*100).toFixed(2)+'%';}
function rbOutcomes(c,compact=false){const records=Object.values(c.state.Meta||{}).filter(x=>x.kind==='research_outcome'&&x.scope==='watchlist');const lines=['RESEARCH OUTCOMES','Reference closes observed when tracking starts; not trades or portfolio returns.'];if(!records.length)lines.push('No paired closing-price baseline yet. /outcomes refreshes Yahoo data.');const ordered=compact?[...records].sort((a,b)=>{const ids=twSelect(twRecent(c,true),3,c).flatMap(twStocks);return (ids.includes(b.stock_id)?1:0)-(ids.includes(a.stock_id)?1:0);}):records;for(const r of ordered.slice(0,compact?2:10)){const pending=r.latest.date===r.baseline.date;lines.push(r.stock_id+' · '+r.baseline.date+' → '+r.latest.date,pending?'Baseline saved; awaiting a later common completed session.':'Stock '+rbPct(r.stock_return)+' · '+r.benchmark_symbol+' '+rbPct(r.benchmark_return)+' · difference '+(r.excess_return>=0?'+':'')+(r.excess_return*100).toFixed(2)+' percentage points');if(!compact)lines.push('Benchmark currency '+r.currency+' · Yahoo fetched '+r.fetched_at+(r.stale?' · STALE / latest refresh unavailable':''));}const unavailable=c.state.Meta?.market_refresh?.failures||[];if(unavailable.length)lines.push('Latest refresh gaps: '+unavailable.map(x=>x.symbol).join(', ')+'. Saved values are retained with timestamps.');const gaps=c.state.Meta?.market_refresh?.outcome_gaps||[];if(gaps.length)lines.push('Unpaired outcome references: '+gaps.map(g=>g.stock_id).join(', ')+'. No return inferred.');if(!compact){const ts=Object.values(c.state.Meta||{}).filter(x=>x.kind==='research_outcome'&&x.scope==='thesis');lines.push('','TEAM THESIS OBSERVATIONS');if(!ts.length)lines.push('No thesis reference series yet; save a hypothesis with /thesis.');for(const r of ts.slice(-5))lines.push(r.stock_id+' · thesis saved '+r.thesis_created_at,'Hypothesis: '+twClean(r.hypothesis,140),r.latest.date===r.baseline.date?'Awaiting a later common session.':rbPct(r.stock_return)+' vs '+r.benchmark_symbol+' '+rbPct(r.benchmark_return)+'; difference '+(r.excess_return*100).toFixed(2)+' percentage points',r.baseline.date+' → '+r.latest.date+' · reference observed '+r.started_at);lines.push('','Returns use Yahoo adjusted closes on common dates. Benchmarks vary by market and are not the competition benchmark. No FX conversion, fees, execution, or portfolio weights are assumed. Price performance does not prove a thesis.','/outcomes refreshes at most once per 6 hours.');}return lines.join('\n');}
function rbCatalysts(c,compact=false){return ccBoard(c,compact);}
function rbCommand(c){if(c.original_action==='changes'){const b=rbDelivered(c)[0];return {text:b?.changes_text?'TICKERWATCH | '+b.created_at+'\n'+b.changes_text:rbDelta(c).text,links:[]};}if(c.original_action==='outcomes')return {text:rbOutcomes(c),links:[]};if(c.original_action==='catalysts')return rbCatalysts(c);const args=c.args||[],now=new Date().toISOString();if(c.original_action==='catalystdone'){const [id,...rest]=args,note=rest.join(' ').trim(),key='team_catalyst_'+id,old=c.state.Meta?.[key];if(!old||note.length<10||note.length>350)return {text:'Use /catalystdone CAT-ID conclusion (10–350 characters).',links:[]};if(old.status==='closed')return {text:'This catalyst plan is already closed.',links:[]};const value={...old,status:'closed',conclusion:note,closed_at:now,revision:old.revision+1};c.state.Meta[key]=value;c.dirty.push({table:'Meta',key,value});return {text:'Catalyst '+id+' closed.\nTeam outcome: '+note+'\nOriginal plan and source retained.',links:[]};}const parts=args.join(' ').split('|').map(s=>s.trim()),[ticker,exchange,date,...extra]=(parts[0]||'').split(/\s+/);const s=c.universe.find(s=>s.ticker.toUpperCase()===String(ticker).toUpperCase()&&s.exchange.toUpperCase()===String(exchange).toUpperCase());const validDate=/^\d{4}-\d{2}-\d{2}$/.test(date||'')&&Number.isFinite(Date.parse(date))&&new Date(date).toISOString().slice(0,10)===date;const validSource=/^https:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}(?::\d{1,5})?(?:[/?#][^\s]*)?$/i.test(parts[3]||'');if(parts.length!==4||!s||extra.length||!validDate||date<now.slice(0,10)||Date.parse(date)>Date.now()+366*86400000||parts[1].length<5||parts[1].length>120||parts[2].length<10||parts[2].length>240||!validSource||parts[3].length>1000)return {text:'Use /catalyst TICKER EXCHANGE YYYY-MM-DD | event (5–120 chars) | metric/question (10–240 chars) | https://source\nChoose a real date within the next year. Team-entered dates remain unverified.',links:[]};const id='CAT-'+rbHash([s.stock_id,date,parts[1]]),key='team_catalyst_'+id,old=c.state.Meta?.[key];if(old)return {text:'This plan is already saved as '+id+'. See /catalysts.',links:[]};if(Object.values(c.state.Meta||{}).filter(t=>t.kind==='team_catalyst'&&t.status==='open').length>=20)return {text:'There are 20 open catalyst plans. Close an existing plan first.',links:[]};const value={kind:'team_catalyst',id,stock_id:s.stock_id,date,title:parts[1],question:parts[2],source_url:parts[3],status:'open',revision:1,created_at:now,created_by:c.from_telegram?'owner':'manual-test',verification:'team_entered_unverified'};c.state.Meta[key]=value;c.dirty.push({table:'Meta',key,value});return {text:'Saved '+id+' as a TEAM PLAN. Date and source are not independently verified.\n'+date+' · '+parts[1]+'\nCheck: '+parts[2]+'\n/catalysts',links:[{label:'Team-supplied source',url:parts[3]}]};}

// Structured, owner-authored research journal. Evidence labels are human judgments.
const TW_THESIS_PREFIX='team_thesis_';
function twTheses(c){return Object.values(c.state.Meta||{}).filter(t=>t?.kind==='team_thesis'&&t.status==='active');}
function twThesisSave(c,key,value){c.state.Meta=c.state.Meta||{};c.state.Meta[key]=value;c.dirty.push({table:'Meta',key,value});}
function twThesisFresh(c,t){return Object.values(c.state.Events||{}).filter(e=>e.status==='analysed'&&e.analysis&&twStocks(e).includes(t.stock_id)&&Date.parse(e.published_on)<=Date.now()&&Date.parse(e.published_on)>=Date.parse(t.created_at)&&!t.evidence.some(p=>p.event_id===e.event_id)).sort((a,b)=>Date.parse(b.published_on)-Date.parse(a.published_on));}
function twThesisAgenda(c){const ts=twTheses(c);if(!ts.length)return 'No team theses saved. /thesis TICKER EXCHANGE hypothesis | invalidation condition';return ts.slice(0,3).map(t=>{const changed=t.evidence.filter(p=>{const e=c.state.Events?.[p.event_id];return !e||researchFingerprint(e)!==p.fingerprint;}).length;return t.stock_id+': '+twThesisFresh(c,t).length+' new case(s) to assess'+(changed?'; '+changed+' linked case(s) changed — reassess labels':'')+'.';}).join('\n')+'\n/theses for the team journal.';}
function twThesisCommand(c){
 const args=c.args||[],action=c.original_action,links=[];
 const usage='Save: /thesis TICKER EXCHANGE hypothesis | what would invalidate it\nView: /thesis TICKER EXCHANGE\nAttach: /evidence TICKER EXCHANGE TW-XXXXXXXX supports|challenges|context reason\nClose: /close TICKER EXCHANGE conclusion\nBoard: /theses';
 if(action==='theses'){
  const ts=twTheses(c),closed=Object.values(c.state.Meta||{}).filter(t=>t?.kind==='team_thesis'&&t.status==='closed');
  return {text:['TICKERWATCH | TEAM THESIS JOURNAL','Team-authored hypotheses; evidence labels are judgments, not verified conclusions.','',...ts.flatMap(t=>[t.stock_id+' · revision '+t.revision,'Hypothesis: '+t.hypothesis,'Invalidated if: '+t.invalidation,'Evidence: '+['supports','challenges','context'].map(label=>t.evidence.filter(p=>p.label===label).length+' '+label).join(' / '),'/thesis '+t.stock_id.replace(':',' '),'']),!ts.length?'No active team hypotheses yet.':'',closed.length+' closed journal(s) retained for audit.',...closed.map(t=>'CLOSED · '+t.stock_id+' · '+twClean(t.conclusion,100)+'\n/thesis '+t.stock_id.replace(':',' ').replace(':',' ')),'',usage].join('\n'),links};
 }
 const [ticker,exchange,...tail]=args;const matches=c.universe.filter(s=>s.ticker.toUpperCase()===String(ticker||'').toUpperCase()&&s.exchange.toUpperCase()===String(exchange||'').toUpperCase());
 if(matches.length!==1)return {text:'Choose one listing from /universe.\n'+usage,links};
 const stock=matches[0],key=TW_THESIS_PREFIX+stock.stock_id,old=c.state.Meta?.[key];
 const now=new Date().toISOString(),actor=c.from_telegram?'owner':'manual-test';
 const record=(value,event)=>{const revision=(old?.revision||0)+1;const history=[...(old?.history||[]),{...event,revision,at:now,actor,run_id:c.run_id}];let dropped=old?.history_dropped||0;const next={...value,kind:'team_thesis',stock_id:stock.stock_id,revision,updated_at:now,history};while(history.length>1&&(history.length>30||JSON.stringify(next).length>40000)){history.shift();dropped++;}next.history_dropped=dropped;if(JSON.stringify(next).length>45000)throw Error('Journal exceeds storage limit; shorten the assessment text.');twThesisSave(c,key,next);};
 if(action==='thesis'&&tail.length){
  const parts=tail.join(' ').split('|').map(s=>s.trim());
  if(parts.length!==2||parts.some(s=>s.length<10||s.length>500))return {text:'Supply a hypothesis and an invalidation condition, each 10–500 characters, separated by |.\n'+usage,links};
  if(old?.status==='active'&&old.hypothesis===parts[0]&&old.invalidation===parts[1])return {text:'This thesis is already saved. No state change.',links};
  // Changing the hypothesis clears current evidence labels; earlier labels remain in the revision audit.
  record({status:'active',hypothesis:parts[0],invalidation:parts[1],created_at:now,evidence:[]},{type:'hypothesis_saved',hypothesis:parts[0],invalidation:parts[1],previous_evidence:old?.evidence||[]});
  return {text:'Team thesis saved for '+stock.stock_id+'.\nHypothesis: '+parts[0]+'\nInvalidated if: '+parts[1]+'\nAttach sources with /evidence. A revised hypothesis starts a fresh evidence assessment.\n/thesis '+stock.stock_id.replace(':',' '),links};
 }
 if(!old)return {text:'No team thesis saved for '+stock.stock_id+'.\n'+usage,links};
 if(action==='close'){
  const conclusion=tail.join(' ').trim();if(conclusion.length<10||conclusion.length>500)return {text:'Use /close '+stock.stock_id.replace(':',' ')+' conclusion (10–500 characters).',links};
  if(old.status==='closed')return {text:'This journal is already closed. View it with /thesis '+stock.stock_id.replace(':',' '),links};
  record({...old,status:'closed',conclusion,closed_at:now},{type:'closed',conclusion});return {text:'Journal closed for '+stock.stock_id+'.\nTeam conclusion: '+conclusion+'\nHypothesis, sources and revision history retained.\n/thesis '+stock.stock_id.replace(':',' '),links};
 }
 if(action==='evidence'){
  if(old.status!=='active')return {text:'This journal is closed. Save a new hypothesis before assessing more evidence.',links};
  const [ref,label,...noteParts]=tail,note=noteParts.join(' ').trim();
  const events=Object.values(c.state.Events||{}).filter(e=>twCaseRef(e).toUpperCase()===String(ref||'').toUpperCase());
  if(events.length!==1||!['supports','challenges','context'].includes(label)||note.length<10||note.length>350)return {text:'Choose an unambiguous case and include your reasoning (10–350 characters).\n'+usage,links};
  const e=events[0];if(e.status!=='analysed'||!e.analysis||!twStocks(e).includes(stock.stock_id))return {text:'Use a validated case matched to '+stock.stock_id+'. See /stock '+stock.stock_id.replace(':',' '),links};
  const fingerprint=researchFingerprint(e),prior=old.evidence.find(p=>p.event_id===e.event_id);
  if(prior?.label===label&&prior.note===note&&prior.fingerprint===fingerprint)return {text:'This evidence assessment is already saved. No state change.',links};
  if(!prior&&old.evidence.length>=6)return {text:'This thesis has 6 evidence assessments. Revise an existing assessment or close the journal before starting a new hypothesis.',links};
  const evidence={event_id:e.event_id,case_ref:twCaseRef(e),label,note,fingerprint,summary:twSummary(e,300),source_url:e.article_evidence?.url||e.url,assessed_at:now};
  record({...old,evidence:[...old.evidence.filter(p=>p.event_id!==e.event_id),evidence]},{type:'evidence_assessed',...evidence});
  return {text:'Team assessment saved: '+twCaseRef(e)+' '+label+' '+stock.stock_id+' thesis.\nSummary: '+evidence.summary+'\nYour reasoning: '+note+'\nThe label is your assessment; it does not prove the thesis.\n/thesis '+stock.stock_id.replace(':',' '),links:[{label:'Assessed source',url:evidence.source_url}]};
 }
 const lines=['TICKERWATCH | '+stock.stock_id+' THESIS',old.status.toUpperCase()+' · revision '+old.revision,'Hypothesis: '+old.hypothesis,'Invalidated if: '+old.invalidation,'Team-authored; source links do not verify the hypothesis.',''];
 for(const p of old.evidence){const e=c.state.Events?.[p.event_id],changed=!e||researchFingerprint(e)!==p.fingerprint;lines.push(p.label.toUpperCase()+' · '+p.case_ref+(changed?' · SOURCE CASE CHANGED — REASSESS':''),'Summary at assessment: '+p.summary,'Team reasoning: '+p.note,'Assessed '+p.assessed_at,'/case '+p.case_ref,'');if(links.length<6)links.push({label:p.case_ref+' · '+p.label,url:p.source_url});}
 if(!old.evidence.length)lines.push('No evidence assessed yet.');
 if(old.status==='active'){const fresh=twThesisFresh(c,old);lines.push('NEW EVIDENCE TO ASSESS · '+fresh.length);for(const e of fresh.slice(0,2))lines.push(twSummary(e,160),'Candidate context only; label after reading. /case '+twCaseRef(e));}
 if(old.conclusion)lines.push('Team conclusion: '+old.conclusion);
 lines.push('','RECENT REVISION AUDIT');for(const h of old.history.slice(-5))lines.push('r'+h.revision+' · '+h.at+' · '+h.actor+' · '+h.type);if(old.history_dropped)lines.push('Older audit entries trimmed to the journal storage limit: '+old.history_dropped+'.');
 lines.push('',usage);return {text:lines.join('\n'),links};
}

// Shared presentation helpers embedded in n8n Code nodes by upgrade_briefing.py.
function twClean(s,n=500){const v=String(s||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();return v.length>n?v.slice(0,n-1).trimEnd()+'…':v;}
function twCaseRef(e){let h=2166136261;for(const ch of String(e.event_id))h=Math.imul(h^ch.charCodeAt(0),16777619);return 'TW-'+(h>>>0).toString(16).padStart(8,'0').toUpperCase();}
function twSummary(e,n=300){return twClean(e.analysis?.summary||e.snippet||e.title,n)||'No readable summary is available.';}
function twScope(e){return /full[_ -]?(article|text)|article[_ -]text|primary[_ -]?page/i.test(e.evidence_scope||'')?'public article excerpt':'headline/feed excerpt';}
function twStocks(e){return [...new Set([...(e.analysis?.impacts||[]).map(p=>p.stock_id),...(e.candidates||[]).map(m=>m.stock_id)])];}
function twChecks(e){
 const t=[e.title,e.snippet,...(e.candidates||[]).map(m=>m.matched)].join(' ').toLowerCase();
 if(/earnings|quarterly|financial results|\beps\b/.test(t))return ['Check the issuer release for actual revenue, EPS, reporting period and accounting basis.','Compare with Bloomberg consensus only on the same period and basis; separate previews from reported results.'];
 if(/oil|crude|opec|oil_revenue/.test(t))return ['Check whether prices, production volumes or costs actually changed; inspect hedging disclosures.','Test the revenue benefit against supply interruptions and cost pressure.'];
 if(/semiconductor|chip|gpu|\bai\b|dsx|export/.test(t))return ['Check orders, shipment timing and disclosed revenue contribution in the issuer announcement.','Look for capacity, export-control or customer-spending constraints.'];
 if(/rate|inflation|central bank|funding|tariff/.test(t))return ['Verify the actual policy decision and timing in the original release.','Identify the documented funding, input-cost or demand channel before extending it to other stocks.'];
 if(/partnership|agreement|launch|product/.test(t))return ['Verify rollout timing, commercial terms and measurable revenue or margin implications.','Check whether the announcement changes guidance or the existing investment thesis.'];
 return ['Read the original announcement and identify the measurable revenue, cost or cash-flow change.','Record what evidence would support or weaken the business-impact hypothesis.'];
}
function twRecent(c,includeReviewed=false){return Object.values(c.state.Events||{}).filter(e=>e.status==='analysed'&&e.analysis&&Date.parse(e.published_on)<=Date.now()&&Date.now()-Date.parse(e.published_on)<=Number(c.cfg.max_news_age_days||7)*86400000&&(includeReviewed||!isResearchReviewed(c,e)));}
function twScore(e){const title=String(e.title||'');return Number(e.analysis?.priority||0)*10+(/announc|launch|results|production|agreement|decision|partner|signals/i.test(title)?4:0)-(/preview|what to expect|ahead of|analyst.*expect|may move|discuss|director on|interview|haji|could.*\?/i.test(title)?12:0);}
function twSelect(events,count=3,c=null){const pool=events.filter(e=>!e.analysis||e.analysis.impacts?.some(i=>pfRelevant(e,i.stock_id))).sort((a,b)=>(c?pfWeight(c,b)-pfWeight(c,a):0)||twScore(b)-twScore(a)||Date.parse(b.published_on)-Date.parse(a.published_on));const chosen=[],seen=new Set();for(const e of pool){const key=e.analysis?.event_type==='macro'?'macro':(e.candidates||[]).find(m=>m.match_type==='direct')?.issuer_id||twStocks(e).join('|');if(seen.has(key))continue;chosen.push(e);seen.add(key);if(chosen.length===count)return chosen;}for(const e of pool){if(!chosen.includes(e))chosen.push(e);if(chosen.length===count)break;}return chosen;}
function twCard(e,index,compact=false,c=null){
 const impacts=e.analysis?.impacts||[],main=impacts[0];
 return [index+'. '+twClean(e.title.replace(/\s[-–—]\s[^-–—]+$/,''),100),
  'SUMMARY · '+twSummary(e,compact?230:330),
  ...(c&&pfCurrent(c)?[pfCaseLine(c,e)]:[]),
  'WATCHLIST · '+twStocks(e).join(', '),
  'WHY IT MATTERS · '+(main?twClean(main.mechanism,compact?180:240):'Impact analysis has not passed validation.'),
  'CHECK NEXT · '+twClean(main?.watch_next||twChecks(e)[0],compact?140:180),
  'UNCERTAINTY · '+twClean(main?.counterpoint||twChecks(e)[1],compact?90:120),
  '/case '+twCaseRef(e)+' · Source '+index].join('\n');
}
function twBuildBriefing(c,ranked,fallback,failed,allFailed){
 const selected=twSelect(ranked,3,c),links=selected.map((e,i)=>({label:'Source '+(i+1)+' · '+twClean(e.source_name||'original coverage',40),url:e.article_evidence?.url||e.url}));
 const lines=['TICKERWATCH | TEAM BRIEF','ARTICLE SUMMARIES · '+new Date().toLocaleDateString('en-GB',{timeZone:'Europe/Paris',day:'numeric',month:'short'}),''];
 if(allFailed)lines.push('COLLECTION FAILED: no fresh coverage. The research below was saved previously.','');
 else if(failed.length)lines.push('PARTIAL COLLECTION · '+failed.length+' source(s) failed.','');
 for(let i=0;i<selected.length;i++)lines.push(twCard(selected[i],i+1,false,c), '');
 if(!selected.length){lines.push('No validated article summaries are available.','');for(const e of fallback.slice(0,2)){lines.push('SOURCE EXCERPT · '+twSummary(e,220),'AI analysis unavailable; /case '+twCaseRef(e),'');links.push({label:'Read source · '+twClean(e.source_name,30),url:e.article_evidence?.url||e.url});}}
 lines.push(rbDelta(c).text,'');
 if(pfCurrent(c))lines.push(pfDashboard(c,true),'');
 const ids=[...new Set(selected.flatMap(twStocks))];
 lines.push('TEAM AGENDA',ids.length?'Start with '+ids.join(', ')+'. Use /focus for the research checklist.':'Use /focus to identify missing evidence.',
  ...(pfCurrent(c)?[]:['Compare two companies: /compare NVDA NASDAQ SHEL LSE']),twTheses(c).length?twThesisAgenda(c):'Build your team journal: /theses','');
 const earnings=Object.values(c.state.Earnings||{}).filter(r=>r.status==='evidence_checked'&&r.facts?.some(f=>f.kind==='reported_eps'||f.kind==='reported_revenue'));
 if(earnings.length){const r=earnings[0];lines.push('REPORTED EARNINGS ON FILE',r.company+': '+r.facts.slice(0,2).map(f=>f.kind.replace('reported_','').toUpperCase()+' '+f.value+(f.kind==='reported_revenue'?' '+f.units:'')+' ('+f.period+', '+f.basis+')').join('; '),'/earnings '+(c.universe.find(s=>s.issuer_id===r.issuer_id)?.stock_id||'TICKER EXCHANGE')+' for quotes and sources.','');}
 const board=rbCatalysts(c,true);for(const e of ccRows(c).slice(0,2))if(links.length<6)links.push({label:'Calendar '+e.stock_id,url:e.source_url});lines.push(board.text,'',rbOutcomes(c,true),'/changes · /outcomes · /catalysts','');
 const latest=c.coverage||{};
 lines.push('COVERAGE · '+(latest.universe_rows||c.universe.length)+' watched listings; '+(c.deferred||0)+' awaiting analysis. '+c.source_status.filter(s=>s.ok&&!s.count).length+' feed(s) returned no articles.',
  'Article text retrieved for '+selected.filter(e=>e.article_evidence?.text).length+'/'+selected.length+' stories; others use headline/feed excerpts. Sources below; audit in /case.');
 return {lines,links,selected};
}
function twFocus(c){const events=twSelect(twRecent(c),5,c),links=[];const lines=['TICKERWATCH | RESEARCH AGENDA',pfCurrent(c)?(pfCurrent(c).mode==='demo'?'Priorities reflect DEMO PORTFOLIO weights.':'Priorities reflect recorded portfolio weights.'):'Priorities across your saved watchlist; no portfolio weights assumed.',''];for(let i=0;i<events.length;i++){const e=events[i];lines.push((i+1)+'. '+twStocks(e).join(', ')+' · '+twClean(e.title,90),'Summary: '+twSummary(e,230),...(pfCurrent(c)?[pfCaseLine(c,e)]:[]),'Research task: '+twChecks(e)[0],'Challenge the thesis: '+(e.analysis.impacts[0]?.counterpoint||twChecks(e)[1]),'/case '+twCaseRef(e),'');links.push({label:'Source '+(i+1),url:e.article_evidence?.url||e.url});}if(!events.length)lines.push('No open, validated research cases in the recent window. Pending headlines are not treated as confirmed analysis.');const calendar=ccBoard(c,true);lines.push(calendar.text);links.push(...calendar.links);return {text:lines.join('\n'),links:links.slice(0,6)};}
function twStock(c){const events=twRecent(c,true).filter(e=>twStocks(e).includes(c.stock.stock_id)).sort((a,b)=>Date.parse(b.published_on)-Date.parse(a.published_on)).slice(0,3);const lines=['TICKERWATCH | '+c.stock.company,'Recent saved research; summaries use the available source excerpt.',''];for(let i=0;i<events.length;i++)lines.push(twCard(events[i],i+1,true,c),'');if(!events.length)lines.push('No recent validated case saved. This is a coverage gap, not a positive or negative signal.');return {text:lines.join('\n'),links:events.map((e,i)=>({label:'Source '+(i+1),url:e.article_evidence?.url||e.url}))};}
function twCompare(c){const [a,ax,b,bx,...extra]=c.args||[];if(!a||!ax||!b||!bx||extra.length)return {text:'Use /compare TICKER EXCHANGE TICKER EXCHANGE\nExample: /compare NVDA NASDAQ ASML AMS',links:[]};const find=(t,x)=>c.universe.filter(s=>s.ticker.toUpperCase()===t.toUpperCase()&&s.exchange.toUpperCase()===x.toUpperCase());const left=find(a,ax),right=find(b,bx);if(left.length!==1||right.length!==1||left[0].stock_id===right[0].stock_id)return {text:'Choose two different, unambiguous listings from /universe.',links:[]};const lines=['TICKERWATCH | RESEARCH COMPARISON','Evidence comparison across the watchlist. No return forecast or winner is inferred.',''],links=[];for(const s of [left[0],right[0]]){const events=twRecent(c,true).filter(e=>twStocks(e).includes(s.stock_id)).sort((a,b)=>Date.parse(b.published_on)-Date.parse(a.published_on));const e=events[0],p=e?.analysis.impacts.find(p=>p.stock_id===s.stock_id);lines.push(s.company+' · '+s.stock_id);if(e){lines.push('Summary: '+twSummary(e,280),'Business channel: '+twClean(p?.mechanism||'Candidate match only.',230),'Key check: '+twChecks(e)[0],'/case '+twCaseRef(e));links.push({label:'Source · '+s.ticker,url:e.article_evidence?.url||e.url});}else lines.push('No recent validated case saved. This is a coverage gap, not a positive or negative signal.');const r=c.state.Earnings?.[s.issuer_id];lines.push('Reported results: '+(r?.status==='evidence_checked'?r.facts.filter(f=>f.kind!=='confirmed_release_date').map(f=>f.kind.replace('reported_','')+' '+f.value+' '+f.units+' · '+f.period+' · '+f.basis).join('; ')||'No reported figures verified.':'not verified.'),'');}lines.push('BEFORE A TEAM DECISION','Compare valuation, guidance, liquidity and benchmark-relative performance in Bloomberg using the same date and currency. Document which evidence would invalidate each thesis.');return {text:lines.join('\n'),links};}

const c=JSON.parse(JSON.stringify($('Persist pending work').first().json));c.dirty=[];
const outputs=$input.all().map(i=>i.json), returnedIds=new Set(outputs.filter(r=>r.event_id).map(r=>r.event_id));
for(const j of c.jobs||[]){if(j.earnings_only||returnedIds.has(j.event.event_id))continue;const e=c.state.Events[j.event.event_id];if(e){e.status='review';e.analysis=null;e.validation_errors=['Analysis sub-workflow failed; inspect its execution.'];e.processed_at=new Date().toISOString();c.dirty.push({table:'Events',key:e.event_id,value:e});}}
for(const r of outputs){
 if(!r.event_id)continue;const e=c.state.Events[r.event_id];if(!e)continue;if(r.article_evidence){e.article_evidence=r.article_evidence;e.evidence_scope='article_text_excerpt';}if(r.article_fetch_status)e.article_fetch_status=r.article_fetch_status;if(!r.earnings_only){e.status=r.status;e.analysis=r.analysis;e.validation_errors=r.validation_errors;e.processed_at=new Date().toISOString();e.analysis_version=c.cfg.analysis_version||'v2';}c.dirty.push({table:'Events',key:e.event_id,value:e});
 if(r.earnings){const pendingKey='earnings_pending_'+r.earnings.issuer_id;const pending=c.state.Meta[pendingKey];if(pending){pending.status='checked';c.dirty.push({table:'Meta',key:pendingKey,value:pending});}c.state.Earnings[r.earnings.issuer_id]=r.earnings;c.dirty.push({table:'Earnings',key:r.earnings.issuer_id,value:r.earnings});}
 if(r.earnings_only)continue;
 const selected=new Set((r.candidates||[]).map(x=>x.stock_id));
 for(const match of e.candidates||[]){const impact=r.analysis?.impacts?.find(p=>p.stock_id===match.stock_id);const k=e.event_id+'|'+match.stock_id;const v={event_id:e.event_id,stock_id:match.stock_id,...match,analysis_status:impact?'analysed':selected.has(match.stock_id)?'review':'candidate_only',impact:impact||null,universe_version:c.cfg.universe_version};c.state.ImpactLinks[k]=v;c.dirty.push({table:'ImpactLinks',key:k,value:v});}
}
const failed=c.source_status.filter(s=>!s?.ok);const allFailed=failed.length===c.source_status.length;
const currentIds=new Set((c.jobs||[]).filter(j=>!j.earnings_only).map(j=>j.event.event_id));
const recent=Object.values(c.state.Events).filter(e=>Number.isFinite(Date.parse(e.published_on))&&Date.parse(e.published_on)<=Date.now()&&Date.now()-Date.parse(e.published_on)<=Number(c.cfg.max_news_age_days||7)*86400000).sort((a,b)=>Date.parse(b.published_on)-Date.parse(a.published_on));

function researchFingerprint(e){
 const a=e.analysis||{};
 const body=JSON.stringify([...(e.article_evidence?[e.article_evidence.url,e.article_evidence.text]:[]),e.title,e.url,e.published_on,a.summary,a.priority,(a.impacts||[]).map(p=>[p.stock_id,p.direction,p.uncertainty,p.mechanism,...(p.watch_next||p.counterpoint?[p.watch_next||'',p.counterpoint||'']:[])])]);
 let h=2166136261;for(let i=0;i<body.length;i++)h=Math.imul(h^body.charCodeAt(i),16777619);return (h>>>0).toString(16);
}
function researchReview(c,e){return c.state.Meta?.['research_review_'+e.event_id];}
function isResearchReviewed(c,e){const r=researchReview(c,e);return r?.status==='reviewed'&&r.fingerprint===researchFingerprint(e);}

const ranked=twSelect(recent.filter(e=>!isResearchReviewed(c,e)&&e.analysis?.priority>=3).sort((a,b)=>pfWeight(c,b)-pfWeight(c,a)||b.analysis.priority-a.analysis.priority).slice(0,10),3,c);
const fallback=recent.filter(e=>!isResearchReviewed(c,e)&&e.status==='review'&&!/\b(prediction|stocks? to (buy|own)|undervalued stocks?|should you (buy|sell|be worried)|millionaire|stock is going to soar)\b/i.test(e.title)&&!(/tencent music/i.test(e.title)&&e.candidates?.every(x=>x.issuer_id==='tencent'))).slice(0,Math.max(0,3-ranked.length));
const now=new Date().toISOString();
const nonempty=c.source_status.filter(s=>s?.ok&&Number(s.count)>0);
const empty=c.source_status.filter(s=>s?.ok&&!Number(s.count));
const detailed=twBuildBriefing(c,ranked,fallback,failed,allFailed);const avExpect=avView({...c,args:[]},'expectations',true);detailed.lines.push('','PROVIDER RESEARCH CONTEXT',avExpect.text);const rendered=uxBrief(c,ranked,fallback,failed,allFailed);const lines=rendered.lines;const reportLinks=rendered.links;
const newEarnings=$input.all().map(i=>i.json.earnings).filter(Boolean);
